submissionValidations:
if(
    routes_missed > routes_completed,
    'Routes missed (' + routes_missed + ') cannot exceed routes completed (' + routes_completed + ').',
    null
)

if(
    recycling_tonnes_collected > tonnes_collected,
    'Recycling tonnes (' + recycling_tonnes_collected + ') cannot exceed total tonnes (' + tonnes_collected + ').',
    null
)

if(
    vehicle_breakdowns > routes_completed + routes_missed,
    'Vehicle breakdowns exceed the total number of attempted routes — please re-check.',
    null
)

values.warning:
if(
    [contamination_pct.maximum] - contamination_pct < 5,
    'Within 5 percentage points of the 100% cap — recheck the sample.',
    if(contamination_pct > 25, 'Contamination above 25% — driver-education programme recommended.', null)
)
